/* Illustrated history and a sourced, state-by-state heritage guide. */
(() => {
  const $=s=>document.querySelector(s);
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  let places=[],geography=null,stateFilter='',typeFilter='',term='';
  function pathOf(g){const polys=g.type==='Polygon'?[g.coordinates]:g.coordinates;return polys.map(p=>p.map(r=>r.map((c,i)=>`${i?'L':'M'}${((c[0]+118.5)*23).toFixed(2)},${((33.5-c[1])*25).toFixed(2)}`).join('')+'Z').join('')).join('');}
  function mapMarkup(selected='') {if(!geography)return '<p class="muted">Elige una entidad en el selector para explorar su patrimonio.</p>';return `<svg class="heritage-map" viewBox="0 0 750 500" role="img" aria-label="Mapa de las 32 entidades mexicanas; usa el selector de estado para navegar con teclado"><title>Explora el patrimonio por entidad</title>${geography.features.map(f=>`<path d="${pathOf(f.geometry)}" class="${String(f.properties.state_code)===String(selected)?'selected':''}" data-guide-state="${f.properties.state_code}"><title>${esc(places.find(p=>p.stateCode===f.properties.state_code)?.state||f.properties.state_name)}</title></path>`).join('')}</svg>`;}
  function catalog(){const host=$('#heritageApp');host.innerHTML=`<div class="heritage-intro"><div id="heritageMapSlot">${mapMarkup(stateFilter)}</div><div class="heritage-search"><label>Estado<select id="heritageState"><option value="">Las 32 entidades</option>${[...new Map(places.map(p=>[p.stateCode,p])).values()].sort((a,b)=>a.state.localeCompare(b.state,'es')).map(p=>`<option value="${p.stateCode}" ${String(p.stateCode)===stateFilter?'selected':''}>${esc(p.state)}</option>`).join('')}</select></label><label>Busca un lugar o una época<input type="search" id="heritageSearch" value="${esc(term)}" placeholder="Ej. Chihuahua, fortificación, Independencia"></label><label>Tipo de lugar<select id="heritageType"><option value="">Todos</option>${[...new Set(places.map(p=>p.kind))].map(k=>`<option ${k===typeFilter?'selected':''}>${esc(k)}</option>`).join('')}</select></label><button class="ghost-btn" id="heritageReset">Limpiar filtros</button><p class="muted">Selección de lugares de las 32 entidades. Algunas tienen varias fichas; el catálogo continúa en ampliación.</p></div></div><p id="heritageCount" role="status"></p><div id="heritageCards" class="heritage-cards"></div><div class="sources-note"><p>Consulta histórica: septiembre de 2026. Cada ficha enlaza a su fuente institucional. La guía no confirma apertura, horarios, precios ni accesibilidad actual; compruébalos con el recinto antes de viajar. Mapa de límites simplificados de referencia: <a href="https://github.com/strotgen/mexico-leaflet" target="_blank" rel="noopener">fuente cartográfica</a>.</p></div>`;
    $('#heritageState').onchange=()=>{stateFilter=$('#heritageState').value;refreshCards();refreshMap();};$('#heritageType').onchange=()=>{typeFilter=$('#heritageType').value;refreshCards();};$('#heritageSearch').oninput=()=>{term=$('#heritageSearch').value;refreshCards();};$('#heritageReset').onclick=()=>{stateFilter='';typeFilter='';term='';catalog();};bindMap();refreshCards();host.setAttribute('aria-busy','false');}
  function bindMap(){$('#heritageApp').querySelectorAll('[data-guide-state]').forEach(p=>p.onclick=()=>{stateFilter=p.dataset.guideState;$('#heritageState').value=stateFilter;refreshCards();refreshMap();});}
  function refreshMap(){$('#heritageMapSlot').innerHTML=mapMarkup(stateFilter);bindMap();}
  function refreshCards(){const found=places.filter(p=>(!stateFilter||String(p.stateCode)===stateFilter)&&(!typeFilter||p.kind===typeFilter)&&norm([p.state,p.name,p.location,p.period,p.history,p.kind].join(' ')).includes(norm(term)));$('#heritageCount').textContent=`${found.length} ${found.length===1?'lugar disponible':'lugares disponibles'}`;$('#heritageCards').innerHTML=found.length?found.map(p=>`<article class="heritage-card"><p class="eyebrow">${esc(p.state)}</p><h2>${esc(p.name)}</h2><p class="heritage-location">${esc(p.location)}</p><div class="topic-meta"><span>${esc(p.kind)}</span><span>${esc(p.period)}</span></div><p>${esc(p.history)}</p><a class="card-link" href="#patrimonio/${p.id}">Explorar este lugar</a></article>`).join(''):'<div class="paper"><h2>No encontramos coincidencias</h2><p>Prueba otro término o limpia los filtros. El catálogo es una selección y no un inventario completo.</p></div>';}
  function placeDetail(p){const host=$('#heritageApp');const mapQuery=encodeURIComponent(p.name+' '+p.location+' '+p.state+' México');host.innerHTML=`<a class="text-link" href="#patrimonio">Volver a la guía</a><article class="heritage-detail"><header><p class="eyebrow">${esc(p.state)} · ${esc(p.kind)}</p><h2>${esc(p.name)}</h2><p class="route-question">${esc(p.location)}</p><span class="topic-tag">${esc(p.period)}</span></header><div class="heritage-detail-grid"><div><h3>La historia del lugar</h3><p class="lead">${esc(p.history)}</p><div class="callout"><strong>Una mirada atenta</strong><p>${esc(p.observe)}</p></div><h3>Para conversar durante la visita</h3><p>${esc(p.question)}</p><details class="teacher-note"><summary>Actividad para el grupo</summary><p>${esc(p.activity||"Registra tres observaciones y una pregunta. Elige una evidencia de la ficha oficial y explica cómo apoya tu respuesta. Separa hechos, interpretaciones y tradiciones.")}</p></details></div><aside class="heritage-visit"><h3>Explora y prepara tu visita</h3><a class="btn btn-primary" href="${esc(p.visitorSource)}" target="_blank" rel="noopener">Consultar el sitio institucional</a><a class="ghost-btn" href="https://www.google.com/maps/search/?api=1&query=${mapQuery}" target="_blank" rel="noopener">Buscar ubicación en el mapa</a><p>El mapa abre una búsqueda por nombre. Confirma el recinto y el acceso correcto antes de trasladarte.</p><p>Revisa con el recinto apertura, horarios, costos y condiciones de acceso. Esta ficha ofrece contexto histórico; no reserva visitas.</p></aside></div><section class="heritage-reference"><h3>Fuente de esta ficha</h3><a href="${esc(p.source)}" target="_blank" rel="noopener">${esc(p.institution)} · ${esc(p.name)}</a><p class="muted">Síntesis educativa de Atlas del Tiempo. Las preguntas y actividades son propuestas docentes. Consulta: septiembre de 2026.</p>${p.route?`<a class="text-link" href="#ruta/${p.route}">Abrir la ruta histórica relacionada</a>`:''}${p.stateCode===22?'<p><a class="text-link" href="#historietas">Ver la Revolución en viñetas</a></p>':''}</section></article>`;host.setAttribute('aria-busy','false');}
  function route(){if(!places.length)return;const hash=location.hash.slice(1);if(hash.startsWith('patrimonio/')){const p=places.find(p=>p.id===hash.split('/')[1]);if(p)placeDetail(p);else $('#heritageApp').innerHTML='<p>Este lugar no está en la guía.</p><a href="#patrimonio">Volver al catálogo</a>';}else if(hash==='patrimonio')catalog();}
  async function initGuide(){try{const r=await fetch('/data/heritage.json');if(!r.ok)throw Error('guide');places=await r.json();catalog();route();try{const g=await fetch('/data/states.geojson');if(!g.ok)throw Error('map');geography=await g.json();if($('#heritageMapSlot'))refreshMap();}catch{/* The searchable catalogue remains functional without the map. */}}catch{$('#heritageApp').innerHTML='<p>No se pudo cargar la guía.</p><button class="ghost-btn" id="retryHeritage">Volver a intentar</button>';$('#heritageApp').setAttribute('aria-busy','false');$('#retryHeritage').onclick=initGuide;}}
  window.addEventListener('hashchange',route);initGuide();
})();
